def calculate_ratio(n):
    if n < 4:
        return 0

    def combinations(n, k):
        import math
        return math.comb(n, k)

    f_n = combinations(n, 3)
    g_n = combinations(n, 4)

    if f_n == 0:
        return float('inf') # Should not happen for n >= 4

    return (g_n**3) / (f_n**4)

# Test for small n
print(f"n=4: {calculate_ratio(4)}")
print(f"n=5: {calculate_ratio(5)}")
print(f"n=6: {calculate_ratio(6)}")
# Test for large n limit
print(f"n=10: {calculate_ratio(10)}")
print(f"n=20: {calculate_ratio(20)}")
